// --- POST /orders ---

const placeOrder = (token: string, body: unknown) =>
  fetch(`${base}/orders`, {
    method: "POST",
    headers: { ...as(token), "content-type": "application/json" },
    body: typeof body === "string" ? body : JSON.stringify(body),
  });

const stockOf = async (id: number) => (await pool.query("select stock from products where id = $1", [id])).rows[0].stock;
const chargesFor = async (orderId: number) =>
  (await pool.query("select amount_cents from payment_calls where kind = 'charge' and idempotency_key = $1", [`order-${orderId}`])).rows;

test("POST /orders charges the total, reduces stock and returns the paid order", async () => {
  const tshirt = await stockOf(1);
  const mug = await stockOf(2);
  // Same product listed twice is merged into one line.
  const res = await placeOrder("bob-token", { items: [{ productId: 2, quantity: 1 }, { productId: 1, quantity: 2 }, { productId: 2, quantity: 2 }] });
  assert.equal(res.status, 201);
  const order = await res.json();
  assert.equal(order.status, "paid");
  assert.equal(order.total_cents, 2 * 2000 + 3 * 1200);
  assert.match(order.payment_id, /^pay_/);
  assert.deepEqual(order.items, [
    { product_id: 1, quantity: 2, price_cents: 2000 },
    { product_id: 2, quantity: 3, price_cents: 1200 },
  ]);
  assert.equal(await stockOf(1), tshirt - 2);
  assert.equal(await stockOf(2), mug - 3);
  assert.deepEqual(await chargesFor(order.id), [{ amount_cents: 7600 }]);
  const { rows } = await pool.query("select user_id from orders where id = $1", [order.id]);
  assert.equal(rows[0].user_id, 2);
  const bobs = await (await fetch(`${base}/orders`, { headers: as("bob-token") })).json();
  assert.ok(bobs.some((o: { id: number }) => o.id === order.id));
});

test("POST /orders with too little stock is 409 and charges nothing", async () => {
  const before = await stockOf(3);
  const calls = (await pool.query("select count(*)::int as n from payment_calls")).rows[0].n;
  const res = await placeOrder("alice-token", { items: [{ productId: 1, quantity: 1 }, { productId: 3, quantity: before + 1 }] });
  assert.equal(res.status, 409);
  assert.equal((await res.json()).error.code, "insufficient_stock");
  assert.equal(await stockOf(3), before);
  assert.equal((await pool.query("select count(*)::int as n from payment_calls")).rows[0].n, calls);
});

test("POST /orders with an unknown product is 404", async () => {
  const res = await placeOrder("alice-token", { items: [{ productId: 999, quantity: 1 }] });
  assert.equal(res.status, 404);
  assert.equal((await res.json()).error.code, "product_not_found");
});

test("POST /orders rejects bad input with 400", async () => {
  const bad = [
    {},
    { items: [] },
    { items: "nope" },
    { items: [null] },
    { items: [{ productId: 1 }] },
    { items: [{ productId: 1, quantity: 0 }] },
    { items: [{ productId: 1, quantity: -1 }] },
    { items: [{ productId: 1, quantity: 1.5 }] },
    { items: [{ productId: "1", quantity: 1 }] },
    { items: [{ productId: 1, quantity: 1001 }] },
    { items: [{ productId: 1, quantity: 600 }, { productId: 1, quantity: 600 }] },
    { items: [{ productId: 1e12, quantity: 1 }] },
    "{not json",
  ];
  for (const body of bad) {
    const res = await placeOrder("alice-token", body);
    assert.equal(res.status, 400, JSON.stringify(body));
    assert.equal((await res.json()).error.code, "invalid_body");
  }
});

test("POST /orders requires a token", async () => {
  const res = await placeOrder("nope", { items: [{ productId: 1, quantity: 1 }] });
  assert.equal(res.status, 401);
});

test("POST /orders gives the stock back and fails the order when the charge fails", async () => {
  const before = await stockOf(1);
  const original = payments.charge;
  payments.charge = async () => { throw new Error("card declined"); };
  try {
    const res = await placeOrder("alice-token", { items: [{ productId: 1, quantity: 3 }] });
    assert.equal(res.status, 502);
    assert.equal((await res.json()).error.code, "payment_failed");
  } finally {
    payments.charge = original;
  }
  assert.equal(await stockOf(1), before);
  const { rows } = await pool.query("select status from orders order by id desc limit 1");
  assert.equal(rows[0].status, "failed");
});

test("POST /orders in parallel never oversells and charges each order once", async () => {
  await pool.query("update products set stock = 5 where id = 3");
  await pool.query("update products set stock = 100 where id = 1");
  // 20 orders at once, mixing line order so lock ordering is exercised; only 5 sneakers exist.
  const results = await Promise.all(
    Array.from({ length: 20 }, (_, i) =>
      placeOrder(i % 2 ? "alice-token" : "bob-token", {
        items: i % 2 ? [{ productId: 3, quantity: 1 }, { productId: 1, quantity: 1 }] : [{ productId: 1, quantity: 1 }, { productId: 3, quantity: 1 }],
      }),
    ),
  );
  const statuses = results.map((r) => r.status).sort();
  assert.equal(statuses.filter((s) => s === 201).length, 5);
  assert.equal(statuses.filter((s) => s === 409).length, 15);
  assert.equal(await stockOf(3), 0);
  assert.equal(await stockOf(1), 95);
  for (const r of results.filter((r) => r.status === 201)) {
    const order = await r.json();
    assert.deepEqual(await chargesFor(order.id), [{ amount_cents: 17000 }]);
  }
});
